yaml:
http_request:
  timeout: 20s
{{#if out.needTime}}time:
  - platform: sntp
    id: addon_{{ iid }}_time
{{#if config.timezone}}    timezone: "{{ config.timezone }}"
{{/if}}{{#if config.clock}}    on_time:
      - seconds: "{{ out.clockTrigger }}"
        then:
          - lvgl.label.update:
              id: {{ widgets.clock }}
              text: !lambda |-
                return id(addon_{{ iid }}_time).now().strftime("{{ config.clockFormat }}");
{{/if}}{{/if}}{{#if out.showAnim}}globals:
  - id: addon_{{ iid }}_frame
    type: int
    restore_value: false
    initial_value: "0"
interval:
  - interval: {{ config.frameSeconds }}s
    id: addon_{{ iid }}_anim
    then:
      - online_image.set_url:
          id: {{ widgets.radar }}__img
          url: !lambda |-
            auto now = id(addon_{{ iid }}_time).now();
            if (!now.is_valid()) return std::string("{{ out.radarUrl }}");
            const int frame = id(addon_{{ iid }}_frame);
            // Aelteste Aufnahme zuerst; das DWD-Raster liegt auf vollen 5 Minuten.
            time_t ts = now.timestamp - (time_t)({{ out.lastFrame }} - frame) * {{ out.frameStepS }};
            ts -= ts % 300;
            struct tm utc;
            gmtime_r(&ts, &utc);
            char stamp[40];
            strftime(stamp, sizeof(stamp), "%Y-%m-%dT%H:%M:%S.000Z", &utc);
            return std::string("{{ out.radarUrl }}") + "&time=" + stamp;
      - lambda: |-
          id(addon_{{ iid }}_frame) = (id(addon_{{ iid }}_frame) + 1) % {{ config.frames }};
{{#if out.showBar}}      - lvgl.bar.update:
          id: {{ widgets.bar }}
          value: !lambda |-
            return id(addon_{{ iid }}_frame);
{{/if}}{{/if}}
